"""Summary statistics for request latencies (microseconds)."""


def mean(values):
    """Arithmetic mean of a non-empty iterable."""
    values = list(values)
    return sum(values) / len(values)


def variance(values):
    """Population variance of a non-empty iterable."""
    count = total = squares = 0.0
    for value in values:
        count += 1
        total += value
        squares += value * value
    return (squares - total * total / count) / count

